POST /v1/tasks/{task_id}/feedback  // API 端点：提交审查反馈
{
    "category": "false_positive",  // 反馈类别：误报（还有 missed_issue/bad_fix 两种）
    "finding": {                    // 被标记为误报的 Finding 详情
        "rule_id": "REL-DEBUG-PRINT",  // 规则 ID：调试输出检测
        "path": "deploy.py",            // 文件路径
        "line": 9,                      // 行号
        "severity": "low",              // 严重级别：低
        "evidence": "print(f\"Deploying to {env} with key {API_KEY}\")"  // 证据：实际代码行
    }
    // 提交后存入 failure_cases 表，resolved=false（未解决）
    // EvolutionEngine 在下次进化时会读取这些未解决的反馈作为学习信号
}

# _collect_feedback()：收集 validation 集上的漏报作为进化信号
# _collect_feedback：内部辅助方法，供类内部其他方法调用
def _collect_feedback(store, cases, prompt):
    reviewer = PromptPolicyReviewer(prompt)
    feedback = []
    for case in cases:
        if case["split"] != "validation":
            continue  # holdout 案例不参与反馈收集
        parsed = parse_unified_diff(case["diff"])
        findings = reviewer.review(case["diff"], parsed)
        matches = one_to_one_match(case["expected_findings"], findings)
        matched = {item.expected_index for item in matches}
        for index, expected in enumerate(case["expected_findings"]):
            if index in matched:
                continue  # 已匹配，不是漏报
            # 记录漏报为 failure_case，供 EvolutionEngine 学习
            store.record_failure_case(task_id, "missed_issue", {
                "finding": finding, "note": "Confirmed validation false negative"
            })
            feedback.append({"task_id": task_id, "finding": finding})
    return feedback
